namespace ks {
// Complete ordinary program browser. SysEx selection Notice5EC0 is an explicit
// separate system operation and is not reachable from any admitted root here.
class StateProgramBrowserService final {
public:
 using Coordinator=StateProgramBrowserCoordinator;using Kind=Coordinator::Kind;using Input=Coordinator::Input;using Request=Coordinator::Request;using Effect=Coordinator::Effect;
 enum class Component {Workflow,Numeric,BankEntry,ReadIndex,WriteIndex,Combine,Timer,Clock,Expand,Semitone,Mark,ProgramLoad,Ui,Notify,Panel,Pack,Held,Routing,Display};
 struct Outcome {Request request=Request::None;unsigned slot=0;uint16_t presentation=0;};
 struct PanelFacts {PanelControlTask indicator{};uint8_t input=0,set=0;};
 explicit StateProgramBrowserService(Kind k):StateProgramBrowserService(k,Input{}){}
 StateProgramBrowserService(Kind k,Input i):coordinator_(k,i){components_=1u<<unsigned(component());}
 Kind kind()const{return coordinator_.kind();}const Input&input()const{return coordinator_.input();}const Coordinator&coordinator()const{return coordinator_;}const auto&summary()const{return coordinator_.summary();}bool complete()const{return coordinator_.complete();}const Effect&effect()const{return effect_;}uint32_t components()const{return components_;}
 Component component()const{if(active_==Request::None)return Component(unsigned(coordinator_.component()));switch(active_){case Request::CommitSingle:case Request::CommitMulti:case Request::LoadSingle:return Component::ProgramLoad;case Request::Ui:case Request::Program:case Request::Bank:case Request::Parts:case Request::Heading:case Request::BankHeading:return Component::Ui;case Request::Notify:return Component::Notify;case Request::Panel:return Component::Panel;case Request::Pack:return Component::Pack;case Request::Held:return Component::Held;case Request::Routing:return Component::Routing;case Request::Character:return Component::Display;default:throw std::logic_error("Invalid browser child component");}}
 const Outcome&outcome(unsigned n)const{if(n>=outcomes_.size()||outcomes_[n].request==Request::None)throw std::logic_error("Missing browser native outcome");return outcomes_[n];}
 const StateFieldService&field(unsigned n)const{return *fields_.at(n);}const StateDisplayService&display(unsigned n)const{return *displays_.at(n);}const StateProgramLoadService*program()const{return program_?&*program_:nullptr;}const StateReloadPanelService*panel()const{return panel_?&*panel_:nullptr;}const StateStoreService*pack()const{return pack_?&*pack_:nullptr;}const StatePlaybackResetService*held()const{return held_?&*held_:nullptr;}const StatePlaybackModeCoordinator&routing(unsigned n)const{return *routing_.at(n);}uint32_t packingBinding()const{return packBinding_;}const PanelFacts&panelFacts()const{return panelFacts_;}
 bool critical()const{if(active_==Request::CommitSingle||active_==Request::CommitMulti||active_==Request::LoadSingle)return program_->critical();if(active_==Request::Ui||active_==Request::Program||active_==Request::Heading||active_==Request::BankHeading||active_==Request::Bank||active_==Request::Parts||active_==Request::Notify)return fields_[activeSlot_]->critical();return false;}
 template<class T>const T*task()const{if(active_==Request::None)return coordinator_.template task<T>();if(active_==Request::CommitSingle||active_==Request::CommitMulti||active_==Request::LoadSingle)return program_->template task<T>();if(active_==Request::Held)return held_->template task<T>();if(active_==Request::Routing)return routing_[activeSlot_]->template task<T>();if constexpr(std::is_same_v<T,StateFieldCoordinator>||std::is_same_v<T,StateApplyService>||std::is_same_v<T,StateDisplayService>||std::is_same_v<T,StateScreenService>||std::is_same_v<T,StateUiRefreshService>||std::is_same_v<T,StateStoreService>||std::is_same_v<T,StateFieldPacketService>||std::is_same_v<T,PanelSettingsLcdService>||std::is_same_v<T,StateSceneCoordinator>||std::is_same_v<T,StateSceneEditCoordinator>||std::is_same_v<T,StateVoiceRefreshService>){if(active_==Request::Ui||active_==Request::Program||active_==Request::Heading||active_==Request::BankHeading||active_==Request::Bank||active_==Request::Parts||active_==Request::Notify)return fields_[activeSlot_]->template task<T>();}if constexpr(std::is_same_v<T,StateReloadPanelService>)return active_==Request::Panel?&*panel_:nullptr;else if constexpr(std::is_same_v<T,StateStoreService>)return active_==Request::Pack?&*pack_:nullptr;else if constexpr(std::is_same_v<T,StateDisplayService>)return active_==Request::Character?&*displays_[activeSlot_]:nullptr;else return nullptr;}
 template<class Peek,class Resolver>static bool admitted(Kind k,const Input&,Peek&&peek,Resolver&&resolver){if(k==Kind::Repeat||k==Kind::Stop||k==Kind::Stopped||k==Kind::Category||k==Kind::Step||k==Kind::Clear)return true;if(peek(0xffed6c)||peek(0xffed6e))return false;const auto wide=[&](uint32_t a){uint32_t v=0;for(unsigned n=0;n<4;++n)v=(v<<8)|uint8_t(peek(a+n));return v;};if(!Coordinator::dataSpan(wide(0x167bc),256)||!Coordinator::dataSpan(wide(0x167c0),256))return false;return StateReloadService::admittedSchema(peek,[&](uint8_t c,uint32_t p){return resolver.schema(c,p);});}
 unsigned nextClocks(int previous=-1)const{if(active_==Request::None)return coordinator_.nextClocks(previous);switch(active_){case Request::CommitSingle:case Request::CommitMulti:case Request::LoadSingle:return program_->nextClocks(previous);case Request::Ui:case Request::Program:case Request::Heading:case Request::BankHeading:case Request::Bank:case Request::Parts:case Request::Notify:return fields_[activeSlot_]->nextClocks(previous);case Request::Panel:return panel_->nextClocks(previous);case Request::Pack:return pack_->nextClocks(previous);case Request::Held:return held_->nextClocks(previous);case Request::Routing:return routing_[activeSlot_]->nextClocks(previous);case Request::Character:return displays_[activeSlot_]->nextClocks(previous);default:return 0;}}
 template<class R,class W,class Resolver>unsigned advanceBefore(unsigned budget,R&&read,W&&write,Resolver&&resolver,int previous=-1){const auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;effect_={};components_|=1u<<unsigned(component());
 if(active_==Request::None){coordinator_.advanceBefore(cost,read,write,previous);effect_=coordinator_.effect();if(coordinator_.request()!=Request::None)startNative(coordinator_.request(),coordinator_.requestInput());}
 else {bool done=false;uint16_t result=0,presentation=coordinator_.requestInput().event;const auto request=active_;switch(request){
 case Request::CommitSingle:case Request::CommitMulti:case Request::LoadSingle:program_->advanceBefore(cost,read,write,[&](uint8_t c,uint32_t p){return resolver.schema(c,p);},previous);effect_={program_->effect().read,program_->effect().write};done=program_->complete();presentation=program_->presentation();break;
 case Request::Ui:case Request::Program:case Request::Bank:case Request::Heading:case Request::BankHeading:case Request::Parts:case Request::Notify:{auto&f=*fields_[activeSlot_];f.advanceBefore(cost,read,write,resolver,previous);effect_={f.effect().read,f.effect().write};done=f.complete();if(done){if(request==Request::Notify){if(!f.sceneRootSummary())throw std::logic_error("Missing browser SceneNotify summary");presentation=f.sceneRootSummary()->presentation;}else{if(!f.lastRefresh())throw std::logic_error("Missing browser UI summary");presentation=f.lastRefresh()->character;}}break;}
 case Request::Panel:{if(const auto*t=panel_->indicatorTask()){panelFacts_.indicator=*t;panelFacts_.input=uint8_t(panel_->panelTask().value());if(t->stage()==PanelControlTask::Stage::CompareToggle)panelFacts_.set=t->set();}panel_->advanceBefore(cost,read,write,[&](uint8_t c,uint32_t p){return resolver.schema(c,p);},previous);effect_={panel_->effect().read,panel_->effect().write};done=panel_->complete();presentation=uint16_t((panel_->panelTask().value()<<8)|21u);break;}
 case Request::Pack:{effect_=packEffect(*pack_);pack_->advanceBefore(cost,read,write,[&](uint32_t p){packBinding_=p;return resolver(p);},previous);done=pack_->complete();break;}
 case Request::Held:held_->advanceBefore(cost,read,write,previous);effect_={held_->effect().read,held_->effect().write};done=held_->complete();break;
 case Request::Routing:{auto&t=*routing_[activeSlot_];t.advanceBefore(cost,read,write,resolver,previous);effect_={t.effect().read,t.effect().write};done=t.complete();break;}
 case Request::Character:{auto&t=*displays_[activeSlot_];effect_={t.endsReadTransfer(),t.endsWriteTransfer()};t.advanceBefore(cost,read,write,previous);done=t.complete();presentation=t.output();break;}
 default:throw std::logic_error("Invalid browser native owner");}
 if(done){outcomes_[activeIndex_].presentation=presentation;coordinator_.resume(result,presentation);active_=Request::None;}}
 components_|=1u<<unsigned(component());return cost;}
private:
 static Effect packEffect(const StateStoreService&s){Effect e;if(const auto*t=s.packTask()){using S=StatePackRefreshTask::Stage;const auto p=t->stage();e.write=p==S::DispatchEntry||p==S::RetainGroup||p==S::DispatchRecipe;e.read=p==S::RestoreGroup||p==S::ReturnEntry||p==S::ReturnAll;}if(const auto*t=s.recipeTask())e.read=t->stage()==StatePackFieldsTask::Stage::ReturnPacked;return e;}
 void startNative(Request q,Input in){active_=q;activeIndex_=coordinator_.requestIndex();if(activeIndex_>=outcomes_.size())throw std::logic_error("Browser native outcome capacity");switch(q){case Request::CommitSingle:case Request::CommitMulti:case Request::LoadSingle:if(program_)throw std::logic_error("Repeated browser program ownership");program_.emplace(q==Request::CommitSingle?StateProgramLoadService::Kind::CommitSingle:q==Request::CommitMulti?StateProgramLoadService::Kind::CommitMulti:StateProgramLoadService::Kind::LoadSingle,StateProgramLoadService::Input{in.event});activeSlot_=0;break;
 case Request::Ui:case Request::Program:case Request::Heading:case Request::BankHeading:case Request::Bank:case Request::Parts:case Request::Notify:if(fieldCount_==fields_.size())throw std::logic_error("Browser field ownership capacity");activeSlot_=fieldCount_++;if(q==Request::Notify)fields_[activeSlot_].emplace(StateSceneCoordinator::Kind::Notify,StateSceneCoordinator::Input{in.event});else fields_[activeSlot_].emplace(q==Request::Ui?StateUiRefreshService::Kind::Refresh:q==Request::Program?StateUiRefreshService::Kind::Program:q==Request::Heading?StateUiRefreshService::Kind::ProgramHeading:q==Request::BankHeading?StateUiRefreshService::Kind::Heading:q==Request::Bank?StateUiRefreshService::Kind::Bank:StateUiRefreshService::Kind::Parts,StateUiRefreshService::Input{in.source,in.event,in.event});break;
 case Request::Panel:if(panel_)throw std::logic_error("Repeated browser panel ownership");panel_.emplace();activeSlot_=0;break;case Request::Pack:if(pack_)throw std::logic_error("Repeated browser packing ownership");pack_.emplace(StateStoreService::Kind::PackAll);activeSlot_=0;break;case Request::Held:if(held_)throw std::logic_error("Repeated browser key-reset ownership");held_.emplace(StatePlaybackResetService::Kind::HeldKeys);activeSlot_=0;break;case Request::Routing:if(routingCount_==routing_.size())throw std::logic_error("Browser routing ownership capacity");activeSlot_=routingCount_++;routing_[activeSlot_].emplace(StatePlaybackModeCoordinator::Kind::Routing);break;case Request::Character:if(displayCount_==displays_.size())throw std::logic_error("Browser display ownership capacity");activeSlot_=displayCount_++;displays_[activeSlot_].emplace(StateDisplayService::Kind::Character,StateDisplayService::Input{0,0,0,in.event,0});break;default:throw std::logic_error("Invalid browser native start");}outcomes_[activeIndex_]={q,activeSlot_,in.event};}
 Coordinator coordinator_;Request active_=Request::None;unsigned activeIndex_=0,activeSlot_=0,fieldCount_=0,displayCount_=0,routingCount_=0;Effect effect_{};uint32_t components_=0,packBinding_=0;std::array<Outcome,16>outcomes_{};std::array<std::optional<StateFieldService>,2>fields_{};std::array<std::optional<StateDisplayService>,4>displays_{};std::array<std::optional<StatePlaybackModeCoordinator>,2>routing_{};std::optional<StateProgramLoadService>program_;std::optional<StateReloadPanelService>panel_;std::optional<StateStoreService>pack_;std::optional<StatePlaybackResetService>held_;PanelFacts panelFacts_{};
};
}
